<?php require_once '../includes/auth.php';login_required();$s=store();if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$n=trim($_POST['name']??'');$slug=preg_replace('/[^a-z0-9]+/','-',strtolower($n));$w=preg_replace('/\D+/','',$_POST['whatsapp']??'');if($n&&$w){if($s){$q=$pdo->prepare('UPDATE stores SET name=?,slug=?,description=?,whatsapp_number=?,delivery_note=? WHERE id=? AND user_id=?');$q->execute([$n,$slug,trim($_POST['description']??''),$w,trim($_POST['delivery_note']??''),$s['id'],$_SESSION['user_id']]);}else{$q=$pdo->prepare('INSERT INTO stores(user_id,name,slug,description,whatsapp_number,delivery_note)VALUES(?,?,?,?,?,?)');$q->execute([$_SESSION['user_id'],$n,$slug,trim($_POST['description']??''),$w,trim($_POST['delivery_note']??'')]);}go('/seller/dashboard.php');}$error='Store name and WhatsApp number are required.';}$s=$s?:['name'=>'','description'=>'','whatsapp_number'=>'','delivery_note'=>''];$title='Store';require '../includes/header.php';?><h1>Store settings</h1><?php if(!empty($error)):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post" class="card card-body col-lg-8"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input class="form-control mb-2" name="name" placeholder="Store name" value="<?=e($s['name'])?>" required><textarea class="form-control mb-2" name="description" placeholder="Description"><?=e($s['description'])?></textarea><input class="form-control mb-2" name="whatsapp" placeholder="2348012345678" value="<?=e($s['whatsapp_number'])?>" required><textarea class="form-control mb-2" name="delivery_note" placeholder="Delivery note"><?=e($s['delivery_note'])?></textarea><button class="btn btn-success">Save</button></form><?php require '../includes/footer.php';?>